fase3.sql:
SELECT * FROM pessoa
WHERE nome LIKE 'Lorena%'
  AND rua_endereco = 'Avenida dos Ipês';

fase10.sql:
SELECT COUNT(*) FROM pessoa
WHERE habilitacao_id IN (SELECT id FROM habilitacao WHERE marca_carro = 'Tesla')
  AND id IN (SELECT pessoa_id FROM evento_checkin WHERE nome_evento = 'Show no Parque');

c3-f2.sql:
SELECT SUM(quantidade) AS total_sem_receita
FROM movimento_estoque
WHERE tipo = 'saida' AND item_id = 1 AND receita_id IS NULL;

c5-f5.sql:
SELECT COUNT(*) AS linhas, SUM(valor_cobrado) AS total
FROM cobranca
WHERE lote = 'L-0830-C';

c7-f1.sql:
SELECT COUNT(*) AS com_espaco
FROM cadastro
WHERE nome <> TRIM(nome);

SELECT COUNT(DISTINCT nome) AS como_esta,
       COUNT(DISTINCT UPPER(TRIM(nome))) AS arrumado
FROM cadastro;

c10-f3.sql:
SELECT momento, parametro, status, linhas
FROM portal_requisicao
WHERE ip = '203.0.113.59' AND linhas > 0 AND parametro ILIKE '%union%';
